package com.farm2market.controller;
import com.farm2market.dto.*; import com.farm2market.entity.*; import com.farm2market.repository.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {final OrderRepository orders;final ProductRepository products;final UserRepository users;OrderController(OrderRepository o,ProductRepository p,UserRepository u){orders=o;products=p;users=u;} @GetMapping("/my") @PreAuthorize("hasRole('BUYER')") public List<Order> my(@AuthenticationPrincipal UserDetails a){return orders.findByBuyerOrderByCreatedAtDesc(users.findByEmail(a.getUsername()).orElseThrow());} @PostMapping @PreAuthorize("hasRole('BUYER')") @Transactional public Map<String,Object> create(@Valid @RequestBody OrderRequest x,@AuthenticationPrincipal UserDetails a){User b=users.findByEmail(a.getUsername()).orElseThrow();Order o=new Order();o.setBuyer(b);o.setDeliveryLocation(x.deliveryLocation());double total=0;User farmer=null;for(OrderLine l:x.items()){Product p=products.findById(l.productId()).orElseThrow();if(!p.isActive()||p.getAvailableQuantity()<l.quantity())throw new RuntimeException("Insufficient quantity for "+p.getName());if(farmer!=null&&!farmer.getId().equals(p.getFarmer().getId()))throw new RuntimeException("Each order must contain products from one farmer");farmer=p.getFarmer();p.setAvailableQuantity(p.getAvailableQuantity()-l.quantity());products.save(p);OrderItem i=new OrderItem();i.setOrder(o);i.setProduct(p);i.setQuantity(l.quantity());i.setPrice(p.getPricePerKg());i.setSubtotal(l.quantity()*p.getPricePerKg());o.getItems().add(i);total+=i.getSubtotal();}o.setFarmer(farmer);o.setTotalAmount(total);Order saved=orders.save(o);return Map.of("id",saved.getId(),"status",saved.getStatus(),"totalAmount",saved.getTotalAmount(),"deliveryLocation",saved.getDeliveryLocation());} @PutMapping("/{id}/status") @PreAuthorize("hasAnyRole('FARMER','ADMIN')") public Order status(@PathVariable Long id,@Valid @RequestBody StatusRequest x,@AuthenticationPrincipal UserDetails a){Order o=orders.findById(id).orElseThrow();if(a.getAuthorities().stream().anyMatch(g->g.getAuthority().equals("ROLE_FARMER"))&&!o.getFarmer().getEmail().equals(a.getUsername()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"You do not own this order");o.setStatus(x.status());o.setUpdatedAt(java.time.LocalDateTime.now());return orders.save(o);}}
